fication:"Fingerprint Unification",fingerprintUnificationHint:"Unify X-Stainless-* headers across users sharing the same OAuth account. Disabling passes through each client's original headers.",metadataPassthrough:"Metadata Passthrough",metadataPassthroughHint:"Pass through client's original metadata.user_id without rewriting. May improve upstream cache hit rates.",cchSigning:"CCH Signing",cchSigningHint:"Sign the billing header in forwarded requests with CCH hash. When disabled, the placeholder is preserved.",claudeOAuthSystemPromptInjection:"Claude OAuth System Blocks",claudeOAuthSystemPromptInjectionHint:"Inject Claude Code-like system blocks for Claude OAuth requests from non-Claude-Code clients. Enabled by default.",claudeOAuthSystemPrompt:"Claude OAuth Expansion Prompt",claudeOAuthSystemPromptPlaceholder:"Leave empty to use the built-in Claude Code expansion prompt.",claudeOAuthSystemPromptHint:"Legacy compatibility: controls only the third injected system block.",claudeOAuthSystemPromptBlocks:"Claude OAuth System Blocks",claudeOAuthSystemPromptBlocksHint:"Each block is saved as JSON with enabled, type, text, and optional cache_control. {'{'}billing_header{'}'} stays dynamic per request; the Claude Code identity and expansion prompts can be edited directly or restored from presets.",systemBlockTitle:"System Block {index}",systemBlockPreset:"Preset",systemBlockPresetBilling:"Billing header",systemBlockPresetIdentity:"Claude Code identity",systemBlockPresetExpansion:"Claude Code expansion",systemBlockPresetCustom:"Custom",systemBlockType:"Type",systemBlockTypeText:"Text",systemBlockText:"Content",systemBlockCacheControl:"Cache control",systemBlockHide:"Hide block details",systemBlockShow:"Show block details",addSystemBlock:"Add block",resetSystemBlocks:"Reset defaults",cacheTTL5m:"5 minutes",cacheTTL1h:"1 hour",anthropicCacheTTL1hInjection:"Anthropic Cache TTL Injection",anthropicCacheTTL1hInjectionHint:"When enabled, existing ephemeral cache_control blocks in Anthropic OAuth/Setup Token request bodies are forced to 1h; response usage is billed back as 5m by default, with account-level TTL billing override taking priority.",rewriteMessageCacheControl:"Rewrite Message Cache Breakpoints",rewriteMessageCacheControlHint:"Default off: preserve client cache_control on message content blocks. When enabled, client breakpoints are stripped and proxy breakpoints are injected for clients that do not manage caching themselves.",clientDatelineNormalization:"Client Dateline Normalization",clientDatelineNormalizationHint:`Default on. Rewrites the "Today's date is …" sentence in Anthropic OAuth/Setup Token requests back to a canonical ASCII apostrophe and hyphen date format, erasing steganographic fingerprint bits some clients inject when they detect a non-official base URL. Applies to system prompts and <system-reminder> blocks only; API-Key accounts are unaffected.`,openaiCodexUserAgent:"OpenAI Codex UA",openaiCodexUserAgentPlaceholder:"codex-tui/0.146.1 (Ubuntu 22.4.0; x86_64) WindowsTerminal (codex-tui; 0.146.1)",openaiCodexUserAgentHint:"The full Codex User-Agent used for all outbound requests, for customizing the OS / arch / terminal fingerprint. Leave empty to build the standard codex-tui identity from the version below (recommended). If set, both the leading and trailing version declarations are synchronized to the version below, so the UA never stays pinned to the release entered here — under capacity pressure the upstream sheds load by client identity and drops stale or non-official identities first with server_is_overloaded.",openaiCodexClientVersion:"Codex client version",openaiCodexClientVersionPlaceholder:"Leave empty to follow auto-sync",openaiCodexClientVersionHint:"The Codex client version this gateway declares upstream, shared by the User-Agent and the version header. Leave empty to use the auto-synced latest stable release; setting a value pins it and stops following auto-sync.",openaiCodexVersionAutoSync:"Auto-sync Codex version",openaiCodexVersionAutoSyncHint:"Fetches the latest stable client version from the official repository every 6 hours, so you never need to upgrade this service just to keep the version current. When disabled, only the version above or the built-in default is used.",openaiCodexVersionSyncedValue:"Currently synced: {version}",claudeCodeClientVersion:"Claude Code client version",claudeCodeClientVersionHint:"The client version this gateway declares upstream when impersonating the official Claude Code CLI. Leave empty to use the auto-synced latest official release; setting a value pins it and stops following auto-sync. The SUB2API_CLAUDE_CLI_VERSION environment variable or built-in version is used only when neither the manual nor synced value is valid.",claudeCodeVersionAutoSync:"Auto-sync Claude Code version",claudeCodeVersionAutoSyncHint:"Fetches the latest Claude Code client version from the official release channel every hour, so you never need to upgrade this service just to keep the version current. When disabled, fetching stops but the previously synced version remains available. The manual version above always takes priority.",claudeCodeVersionSyncedValue:"Currently synced: {version}",codexHardeningTitle:"Codex Settings",codexTicketEnabled:"Codex ticket harvest",codexTicketEnabledDesc:"Controls background acquisition and injection. Server configuration selects turn-state tickets or verified Cookies with direct WS. Turning this off restores the original forwarding policy.",codexTicketHarvestProxy:"Codex harvest proxy",codexTicketHarvestProxyDesc:"Used for background HTTP acquisition. Changes apply to subsequent probes without a restart. Cookie WS traffic connects directly to the upstream. Paste a full HTTP, HTTPS, or SOCKS5h proxy URL including credentials. Use {'{'}session{'}'} or {'{'}SESSION{'}'} in the username or password to change the proxy session for each Cookie acquisition; whether the egress IP changes depends on your provider. Leave blank when saving to keep the stored value.",codexTicketHarvestProxyPlaceholder:"http://user:pass{'@'}proxy.example.com:1080",codexTicketHarvestProxyConfigured:"Configured (password hidden). Paste a full new proxy URL to replace it.",codexClientRestrictionTitle:"Codex client restriction",codexHardeningDesc:"Only affects OpenAI OAuth accounts with 'Codex official clients only' enabled (global). Beyond User-Agent/Originator, harden the decision with a version range, an engine-fingerprint gate, and black/whitelists.",minCodexVersion:"Min Codex Version",minCodexVersionPlaceholder:"e.g. 0.142.0",maxCodexVersion:"Max Codex Version",maxCodexVersionPlaceholder:"e.g. 0.200.0",codexVersionHint:"Official clients only: checks their version against the [min, max] range. Leave a side empty to not limit it.",codexFingerprintSignals:"Codex engine fingerprint signals",codexFingerprintSignalsDesc:"Define engine-fingerprint signals: every Required signal must match (AND); within a row, '/'-separated variants are OR'd. None checked = not enforced. Default checks only the x-codex- prefix. Types: header exact / header prefix / body path.",codexFpTypeHeaderExact:"Header exact",codexFpTypeHeaderPrefix:"Header prefix",codexFpTypeBodyPath:"Body path",codexFpMatchPlaceholder:"match; '/'-separate variants (e.g. session-id / session_id or x-codex-)",codexFpRequired:"Required",codexFingerprintNoRequiredWarn:"No signal is marked Required — the engine-fingerprint gate is inactive, allowing every candidate that passes identity/version. Check at least one signal to enable it.",codexAllowAppServer:"Codex app-server",codexAllowAppServerDesc:"Allow third-party clients that embed the Codex engine and connect over the app-server protocol (e.g. Claude Code's codex plugin). Off by default; when on, such clients are allowed once they pass the engine-fingerprint gate (the signal list below); off = only official clients and the whitelist are allowed.",codexBlacklist:"User-Agent/Originator Blacklist",codexBlacklistDesc